export interface KeyValueStorage {
  get(key: string): Promise<string | undefined>;
  set(key: string, value: string): Promise<void>;
  delete(key: string): Promise<void>;
  keys(): Promise<string[]>;
}

export interface SecretStoreOptions {
  storage: KeyValueStorage;
  masterPassword: string;
}

export interface SecretStore {
  put(owner: string, name: string, value: string): Promise<void>;
  get(owner: string, name: string): Promise<string | undefined>;
  list(owner: string): Promise<string[]>;
  remove(owner: string, name: string): Promise<boolean>;
}

export async function createSecretStore(
  options: SecretStoreOptions,
): Promise<SecretStore> {
  const { storage, masterPassword } = options;

  // Constants
  const SALT_KEY = '\x00secret-store:salt';
  const INDEX_PREFIX = '\x00secret-store:index:';
  const DATA_PREFIX = '\x00secret-store:data:';
  const PBKDF2_ITERATIONS = 100_000;
  const KEY_LENGTH = 32; // 256 bits
  const NONCE_LENGTH = 12; // 96 bits for GCM

  // Helper functions
  function toBase64(bytes: Uint8Array): string {
    let binary = '';
    for (const b of bytes) binary += String.fromCharCode(b);
    return btoa(binary);
  }

  function fromBase64(s: string): Uint8Array {
    const binary = atob(s);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  function encodeKey(owner: string, name: string): string {
    return DATA_PREFIX + toBase64(new TextEncoder().encode(owner)) + '|' + toBase64(new TextEncoder().encode(name));
  }

  function encodeIndexKey(owner: string): string {
    return INDEX_PREFIX + toBase64(new TextEncoder().encode(owner));
  }

  function makeAAD(owner: string, name: string): Uint8Array {
    // Use a separator that can't appear in the encoded form
    const enc = new TextEncoder();
    const ownerBytes = enc.encode(owner);
    const nameBytes = enc.encode(name);
    const aad = new Uint8Array(ownerBytes.length + 1 + nameBytes.length);
    aad.set(ownerBytes, 0);
    aad[ownerBytes.length] = 0; // null separator
    aad.set(nameBytes, ownerBytes.length + 1);
    return aad;
  }

  // Get or create salt
  let saltStr = await storage.get(SALT_KEY);
  let salt: Uint8Array;
  if (saltStr === undefined) {
    salt = crypto.getRandomValues(new Uint8Array(16));
    saltStr = toBase64(salt);
    await storage.set(SALT_KEY, saltStr);
  } else {
    salt = fromBase64(saltStr);
  }

  // Derive key
  const enc = new TextEncoder();
  const passwordKey = await crypto.subtle.importKey(
    'raw',
    enc.encode(masterPassword),
    'PBKDF2',
    false,
    ['deriveKey']
  );

  const aesKey = await crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt: salt as unknown as BufferSource,
      iterations: PBKDF2_ITERATIONS,
      hash: 'SHA-256',
    },
    passwordKey,
    { name: 'AES-GCM', length: KEY_LENGTH * 8 },
    false,
    ['encrypt', 'decrypt']
  );

  return {
    async put(owner: string, name: string, value: string): Promise<void> {
      const nonce = crypto.getRandomValues(new Uint8Array(NONCE_LENGTH));
      const aad = makeAAD(owner, name);
      const plaintext = enc.encode(value);

      const ciphertext = await crypto.subtle.encrypt(
        { name: 'AES-GCM', iv: nonce, additionalData: aad as BufferSource },
        aesKey,
        plaintext
      );

      // Combine nonce + ciphertext (which includes tag)
      const combined = new Uint8Array(NONCE_LENGTH + ciphertext.byteLength);
      combined.set(nonce, 0);
      combined.set(new Uint8Array(ciphertext), NONCE_LENGTH);

      const storageKey = encodeKey(owner, name);
      await storage.set(storageKey, toBase64(combined));

      // Update index
      const indexKey = encodeIndexKey(owner);
